INSERT INTO psychological_frameworks (framework_name, neural_target, primary_trigger, narrative_tone, visual_style, voiceover_guidelines, instagram_format, is_default) VALUES ('COCA_COLA_EMOTIONAL', 'Hippocampus & Prefrontal Cortex (episodic memory, social-reward valuation)', 'Nostalgia, tradition and belonging. BioLife is positioned as the quiet, constant presence at the family dastarkhan - the water that is always on the table when the people you love are together.', 'Warm, slow, respectful, multi-generational; the product is a supporting character, family is the hero', 'Golden-hour or warm tungsten light (2700-3200K), soft diffusion, slow dolly-ins and gentle handheld, 24fps, shallow depth of field on hands and faces, long takes (3-5s), steam and candle/fire glow, product appears late (after second 6) and is poured for someone else, never for oneself', '{"language_priority": ["uz-Latn", "ru"], "voice": "Mature, calm male or female voice; conversational, like a relative speaking at the table", "pace_wpm": 110, "music": "Soft dutar / rubab motif or piano; no drops", "do": ["Use family words: oila, dasturxon, mehmon, ona, buvi", "Speak about moments, not features", "End with a shared toast of water"], "dont": ["Hard sell or discount talk", "Fast cuts", "Individualistic ''me-first'' framing"], "sample_hooks": {"uz": ["Butun oila bir dasturxon atrofida.", "Eng qadrli lahzalar - eng toza suv bilan."], "ru": ["Вся семья за одним дастарханом.", "Самые тёплые моменты - с самой чистой водой."]}}'::jsonb, '{"reel_length_s": [20, 30], "hook_window_s": 3, "avg_shot_length_s": 3.5, "aspect_ratio": "9:16", "cta_style": "soft: ''Share with family'' / ''Oilangiz bilan ulashing''"}'::jsonb, FALSE);
INSERT INTO psychological_frameworks (framework_name, neural_target, primary_trigger, narrative_tone, visual_style, voiceover_guidelines, instagram_format, is_default) VALUES ('PEPSI_BEHAVIORAL_DOPAMINE', 'Dopamine reward pathway (ventral striatum) & gustatory / insular cortex (temperature and thirst signals)', 'Instant refreshment through contrast: heat vs ice, heavy vs light, thirst vs relief. The viewer should almost physically feel the first cold sip.', 'Energetic, punchy, youthful, sensory; short sentences, onomatopoeia (pshhh, click, glug)', 'High-key hard sunlight, heat-haze shimmer, macro shots of condensation droplets running down the bottle, ice cracking, 120fps slow-motion pour intercut with fast 0.5-1s cuts, whip pans, cold blue-teal grade on the product vs warm orange grade on the environment, product visible in the first 1.5 seconds', '{"language_priority": ["uz-Latn", "ru"], "voice": "Young, energetic; or no voiceover and ASMR sound design only (bottle cap click, ice, pour, exhale)", "pace_wpm": 160, "music": "Upbeat Uzbek pop / trap beat with a hard drop on the first sip", "do": ["Lead with the sound of the cap or ice", "Show temperature numbers (+43°C) on screen", "One benefit per clip"], "dont": ["Slow openings", "More than 12 words of on-screen text", "Showing drinking during Ramadan fasting hours"], "sample_hooks": {"uz": ["+43°C. Bitta qultum - va hammasi o''zgaradi.", "Issiqqa qarshi - muzdek BioLife."], "ru": ["+43°C. Один глоток - и всё меняется.", "Жара? Ледяной BioLife."]}}'::jsonb, '{"reel_length_s": [7, 15], "hook_window_s": 1.5, "avg_shot_length_s": 0.8, "aspect_ratio": "9:16", "cta_style": "direct: ''Grab one cold'' / ''Muzdekini oling''"}'::jsonb, FALSE);
INSERT INTO psychological_frameworks (framework_name, neural_target, primary_trigger, narrative_tone, visual_style, voiceover_guidelines, instagram_format, is_default) VALUES ('HYBRID_SPRING_RENEWAL', 'Combined: hippocampal memory (tradition) + dopaminergic novelty response (freshness, new beginnings)', 'Renewal and purity: nature waking up, a clean start, the body shaking off winter heaviness - wrapped in family and seasonal tradition', 'Bright, optimistic, gentle energy; poetic but light', 'Soft natural daylight, pastel palette (blossom pink, fresh green, clear water blue), medium-paced cuts (1.5-2.5s), rack focus from blossoms to bottle, drone or gimbal glides through orchards and mahallas, water refracting sunlight', '{"language_priority": ["uz-Latn", "ru"], "voice": "Light, friendly female or young adult voice", "pace_wpm": 130, "music": "Acoustic, birdsong layer, uplifting build", "do": ["Tie freshness of spring to purity of water", "Show generations together outdoors"], "dont": ["Heavy dark grades", "Aggressive urgency"], "sample_hooks": {"uz": ["Bahor keldi - hamma narsa yangidan boshlanadi.", "Tabiat uyg''onadi. Siz ham."], "ru": ["Пришла весна - всё начинается заново.", "Природа просыпается. И вы тоже."]}}'::jsonb, '{"reel_length_s": [12, 20], "hook_window_s": 2, "avg_shot_length_s": 2.0, "aspect_ratio": "9:16", "cta_style": "inviting: ''Start fresh'' / ''Yangidan boshlang''"}'::jsonb, TRUE);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('osh', 'Osh (Palov)', 'Плов (Ош)', 'Heavy Rice', 'Extremely High', 'HOT', 'Rice cooked in rendered lamb tail fat (dumba) and cottonseed oil, lamb or beef, yellow and red carrots, whole garlic heads, chickpeas, cumin (zira), barberry; served from a large kazan', 'Very high fat load coats the palate and slows gastric emptying; salt and cumin raise thirst; post-meal heaviness and drowsiness, especially after midday wedding or Thursday osh', 'Ice-cold still water (4-6°C) against hot fat creates a strong temperature contrast that rinses the fatty film from the tongue and resets taste between spoonfuls; clean neutral taste does not compete with cumin and carrot sweetness; sipping replaces sugary sodas at the table', '1.5L PET', ARRAY['0.5L PET', '5L/10L Family Pack']::biolife.sku_type[], ARRAY['Thursday/Friday family osh', 'Wedding morning osh (nahor oshi)', 'Guests at home', 'Osh centers at lunch']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('shashlik', 'Shashlik (Kabob)', 'Шашлык', 'Grilled Meat', 'High', 'HOT', 'Lamb, beef or liver on skewers alternating with fat pieces, charcoal smoke, black pepper, cumin, raw onion with vinegar and dill; served with non', 'Smoke, salt and pepper dry the mouth; charred fat is rich and heavy; raw onion leaves a sharp aftertaste; eaten outdoors in heat, which adds to thirst', 'Cold water with a clean, light mineral taste cuts through smoky fat and onion sharpness and refreshes the palate between skewers; bottle condensation next to the grill is a strong visual contrast of fire vs cold', '0.5L PET', ARRAY['1.5L PET', '0.33L Glass']::biolife.sku_type[], ARRAY['Evening choyxona', 'Picnics in the mountains (Chimgan, Chorvoq)', 'Street food at night', 'Men''s gatherings (gap)']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('somsa', 'Tandir somsa', 'Самса тандырная', 'Baked Pastry', 'High', 'HOT', 'Layered puff dough brushed with tallow or butter, filled with minced lamb, onion and lamb tail fat, black pepper and cumin; baked on tandir walls, sesame on top', 'Buttery dough plus fatty filling is dense and dry; hot juice and flaky crumbs leave the mouth greasy and thirsty; common grab-and-go breakfast or snack', 'A cold sip after each bite gives a refreshing contrast to the hot, greasy pastry and clears crumbs and fat from the palate; the on-the-go 0.5L format matches the street-snack moment', '0.5L PET', ARRAY['0.33L Glass']::biolife.sku_type[], ARRAY['Morning commute', 'Bazaar visit', 'Quick lunch', 'Road trips']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('kazan_kabob', 'Qozon kabob', 'Казан-кебаб', 'Grilled Meat', 'Extremely High', 'HOT', 'Lamb ribs or beef fried in a kazan in their own fat with whole potatoes, onion, garlic, cumin and salt; crusty and oily', 'Deep-fried meat and fat-soaked potatoes are very greasy and salty; strong thirst and heaviness afterwards', 'Ice-cold water balances the grease and salt with a clean, cold finish; sharing a 1.5L bottle fits the communal kazan serving', '1.5L PET', ARRAY['0.5L PET']::biolife.sku_type[], ARRAY['Weekend family lunch', 'Outdoor gatherings', 'Restaurants (Besh Qozon style)']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('lagmon', 'Lag''mon', 'Лагман', 'Dough/Noodles', 'High', 'HOT', 'Hand-pulled wheat noodles with beef or lamb, bell pepper, tomato, radish, garlic; spicy rich broth or fried (qovurma lag''mon) version; chili, vinegar and garlic sauce on the side', 'Chili and garlic heat, salty broth and heavy dough; sweating and thirst during and after the meal', 'Cold still water calms chili heat and refreshes between mouthfuls without adding sugar or gas that would amplify fullness from the dough', '0.5L PET', ARRAY['1.5L PET']::biolife.sku_type[], ARRAY['Weekday lunch', 'Uyghur/Dungan cafes', 'Winter dinner']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('manti', 'Manti', 'Манты', 'Dough/Noodles', 'High', 'HOT', 'Steamed thin-dough dumplings filled with chopped lamb or beef, onion and lamb tail fat (sometimes pumpkin), black pepper and cumin; served with sour cream (qatiq) or chili', 'Hot fatty juice inside each dumpling, heavy dough; rich and filling, leaves a greasy aftertaste', 'A cold, clean sip after the hot juice refreshes the mouth and removes the fatty aftertaste; supports eating slowly at family dinners', '1.5L PET', ARRAY['0.5L PET']::biolife.sku_type[], ARRAY['Family dinner', 'Guests', 'Cold-season evenings']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('norin', 'Norin', 'Нарын', 'Dough/Noodles', 'High', 'COLD', 'Very thinly cut boiled dough noodles mixed with finely sliced boiled horse meat and horse sausage (qazi), onion and black pepper; served cold or room temperature, sometimes with hot broth on the side', 'Horse fat and qazi are rich and salty; black pepper builds thirst; commonly eaten at weddings and morning gatherings in Tashkent', 'Because norin is served cold, the pairing is not a temperature contrast but a salt-and-fat balance: light, clean water softens the saltiness of qazi and pepper and keeps the palate fresh; glass bottle fits festive tables', '0.33L Glass', ARRAY['0.5L PET', '1.5L PET']::biolife.sku_type[], ARRAY['Wedding tables', 'Nahor oshi mornings', 'Winter festive tables']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('sumalak', 'Sumalak', 'Сумаляк', 'Ritual Dish', 'Moderate', 'WARM', 'Sprouted wheat juice slowly cooked with flour and oil in a huge kazan through the night, stirred by women in turns; naturally sweet, thick, no added sugar', 'Thick, sticky, sweet paste; eaten after a sleepless night of cooking and singing, at dawn', 'Clean water rinses the sweet, sticky texture and refreshes after an all-night ritual; the pure-water message matches Navruz themes of renewal', '5L/10L Family Pack', ARRAY['1.5L PET']::biolife.sku_type[], ARRAY['Navruz night (sumalak sayli)', 'Mahalla gatherings in March']::text[]);
INSERT INTO national_dishes_pairing (key, dish_name_uz, dish_name_ru, dish_category, caloric_density, serving_temperature, fat_and_spice_profile, physiological_impact, biolife_pairing_mechanics, recommended_sku, alternative_skus, typical_occasions) VALUES ('shurva', 'Sho''rva', 'Шурпа', 'Soups/Stew', 'Moderate', 'HOT', 'Rich lamb broth with large pieces of meat on the bone, potatoes, carrots, onion, chickpeas, tomato; fatty surface, herbs (dill, coriander), black pepper', 'Warming, salty and fatty broth; common in cold months and as a first dish at iftar or gatherings', 'Room-temperature or cool (not ice-cold) water after hot broth balances salt and fat; in winter the message is steady hydration rather than a heat-relief shock', '1.5L PET', ARRAY['5L/10L Family Pack']::biolife.sku_type[], ARRAY['Winter family dinner', 'Iftar starter', 'Cold-weather recovery']::text[]);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('new_year', 'Yangi yil', 'Новый год', 'Dec 20 - Jan 3 (peak Dec 31)', 'GREGORIAN_RANGE', 12, 20, 1, 3, NULL, NULL, NULL, 90, 'Cold (-5°C to +5°C), heated dry indoor air, late nights, many heavy festive meals in a row (osh, norin, salads with mayonnaise, meat platters); low daily water intake because thirst is weak in the cold', 'Festive joy, family warmth, nostalgia for the passing year, hope, children''s excitement', ARRAY['Family dastarkhan on Dec 31 with osh and Olivier salad', 'Decorated yolka (New Year tree)', 'Ded Moroz and Qorbobo visits for children', 'Watching the President''s address and fireworks', 'Visiting relatives on Jan 1']::text[], ARRAY['Yolka lights', 'Snow on mahalla rooftops', 'Fireplace/sandal warmth', 'Clock striking midnight', 'Glass bottle on a festive table']::text[], '{"note": "Present BioLife as the alcohol-free toast; never show alcohol."}'::jsonb, '{"featured_dish_keys": ["osh", "norin", "shashlik"], "sku_focus": ["0.33L Glass", "5L/10L Family Pack"], "public_holiday_dates": ["01-01"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('winter_cold_season', 'Qish mavsumi', 'Зимний сезон', 'Dec 1 - Feb 28/29', 'GREGORIAN_RANGE', 12, 1, 2, 29, NULL, NULL, NULL, 10, 'Cold-weather lethargy; weak thirst signal so people drink less water; dry indoor heating; heavier diet (shurva, manti, lagmon, dimlama); tea replaces water', 'Cozy, home-centred, slower rhythm, desire for comfort and warmth', ARRAY['Sitting around the sandal (heated low table) in rural homes', 'Long evening tea (choy) sessions', 'Indoor family dinners with soups and dumplings', 'Winter weddings in restaurants']::text[], ARRAY['Steaming kazan', 'Snowy mahalla street', 'Fireplace/sandal warmth', 'Knitted socks and blankets', 'Frost on windows']::text[], '{"note": "Do not promote ice-cold drinking in freezing weather; message = daily hydration habit and table water for heavy meals."}'::jsonb, '{"featured_dish_keys": ["shurva", "manti", "lagmon"], "sku_focus": ["5L/10L Family Pack", "1.5L PET"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('homeland_defenders_day', 'Vatan himoyachilari kuni', 'День защитников Родины', 'January 14', 'FIXED_DATE', 1, 14, 1, 14, NULL, NULL, NULL, 60, 'Mid-winter cold; normal winter diet', 'Pride, respect for fathers, brothers and servicemen; gratitude', ARRAY['Congratulating men in the family and at work', 'Small gifts and family dinners']::text[], ARRAY['Uzbek flag', 'Father and son', 'Strength and discipline']::text[], '{"note": "Respectful tone; no military weapons imagery in ads."}'::jsonb, '{"featured_dish_keys": ["osh", "shashlik"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('spring_preparation', 'Bahorga tayyorgarlik', 'Подготовка к весне', 'Feb 15 - Mar 7', 'GREGORIAN_RANGE', 2, 15, 3, 7, NULL, NULL, NULL, 35, 'End-of-winter fatigue, low energy and vitamin deficit after months of heavy food; first warm days (+12-15°C) raise activity', 'Anticipation, desire for a fresh start and lighter lifestyle', ARRAY['Spring cleaning of homes (bahor tozaligi)', 'Planning Navruz and sumalak', 'First walks in parks', 'Buying first greens (ko''kat) for somsa and chuchvara']::text[], ARRAY['Melting snow', 'First green shoots', 'Open windows', 'Clear water stream']::text[], '{}'::jsonb, '{"featured_dish_keys": ["somsa", "shurva"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('womens_day', 'Xalqaro xotin-qizlar kuni', 'Международный женский день', 'March 8 (campaign window Mar 4-8)', 'FIXED_DATE', 3, 4, 3, 8, NULL, NULL, NULL, 80, 'Early spring, mild (+10-16°C); festive lunches and cafe visits', 'Gratitude, tenderness, care for mothers, wives, daughters and teachers', ARRAY['Flowers (tulips, mimosa) for every woman', 'Men cooking or ordering food at home', 'Office celebrations', 'Children''s performances at school']::text[], ARRAY['Tulips and mimosa', 'Mother''s hands', 'Glass bottle with a ribbon', 'Morning light in the kitchen']::text[], '{"note": "Celebrate care and respect; avoid objectifying imagery; modest styling consistent with local norms."}'::jsonb, '{"featured_dish_keys": ["somsa"], "sku_focus": ["0.33L Glass"], "public_holiday_dates": ["03-08"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('navruz', 'Navro''z', 'Навруз', 'March 21 (campaign window Mar 14-25)', 'FIXED_DATE', 3, 14, 3, 25, NULL, NULL, NULL, 90, 'Spring equinox, +12-20°C; sleepless sumalak night; festive heavy food (osh, somsa with greens, halim); more time outdoors', 'Renewal, national pride, communal joy, generosity, reconciliation', ARRAY['Sumalak preparation through the night by women of the mahalla', 'Sayils (festivals) with national games (kurash, ulak/kupkari)', 'Visiting elders and neighbours', 'Cooking ko''k somsa and ko''k chuchvara with spring greens', 'Wearing atlas and adras clothing']::text[], ARRAY['Huge sumalak kazan', 'Spring blossoms (apricot, almond)', 'Atlas silk patterns', 'Doira drum', 'Green wheat sprouts on the table']::text[], '{"note": "If Navruz overlaps Ramadan (e.g. 2026), Ramadan guardrails take precedence."}'::jsonb, '{"featured_dish_keys": ["sumalak", "osh", "somsa"], "sku_focus": ["5L/10L Family Pack", "1.5L PET"], "public_holiday_dates": ["03-21"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('spring_blossoms', 'Bahor gullari', 'Весеннее цветение', 'Mar 1 - Apr 30', 'GREGORIAN_RANGE', 3, 1, 4, 30, NULL, NULL, NULL, 25, 'Warming (+15-25°C), more walking and outdoor activity, first mild thirst of the year; seasonal allergies for some', 'Lightness, optimism, romance, energy returning', ARRAY['Walks in parks and orchards', 'Photo shoots under apricot and cherry blossoms', 'Tulip festivals in the mountains (Chimgan, Zomin)', 'Weekend picnics']::text[], ARRAY['Apricot and almond blossoms', 'Wild red tulips', 'Clear mountain stream', 'Sunlight through water']::text[], '{}'::jsonb, '{"featured_dish_keys": ["somsa", "shashlik"], "sku_focus": ["0.5L PET"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('choyxona_opening', 'Choyxonalar ochilishi', 'Открытие летних чайхан', 'Apr 1 - May 31', 'GREGORIAN_RANGE', 4, 1, 5, 31, NULL, NULL, NULL, 40, 'Warm (+20-30°C) afternoons, evenings outdoors on tapchan (raised platforms), long meals of osh and shashlik', 'Friendship, relaxation after work, male social bonding, leisurely conversation', ARRAY['Gap (rotating friends'' gatherings) at choyxona', 'Tapchans set up by canals and under trees', 'Osh cooked outdoors in kazans', 'Green tea after the meal']::text[], ARRAY['Tapchan under a mulberry tree', 'Kazan on open fire', 'Pialas of green tea', 'Canal (ariq) water', 'Bottles chilling in a bucket of ice']::text[], '{}'::jsonb, '{"featured_dish_keys": ["osh", "shashlik", "kazan_kabob"], "sku_focus": ["1.5L PET", "0.5L PET"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('memorial_day', 'Xotira va qadrlash kuni', 'День памяти и почестей', 'May 9', 'FIXED_DATE', 5, 9, 5, 9, NULL, NULL, NULL, 75, 'Warm late spring (+25°C); ceremonies outdoors', 'Remembrance, respect for veterans and elders, quiet gratitude', ARRAY['Laying flowers at memorials', 'Honouring veterans and elders', 'Family visits to grandparents']::text[], ARRAY['Flowers at memorials', 'Elders'' hands', 'Quiet morning light']::text[], '{"mode": "LOW_KEY", "note": "No sales push, no discounts, no humour; brand message limited to respect and remembrance."}'::jsonb, '{"featured_dish_keys": ["osh"], "public_holiday_dates": ["05-09"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('summer_season', 'Yoz mavsumi', 'Летний сезон', 'Jun 1 - Aug 31', 'GREGORIAN_RANGE', 6, 1, 8, 31, NULL, NULL, NULL, 15, 'Heat +33°C to +40°C, heavy sweating, fast dehydration, fatigue in the afternoon; peak ice-water demand', 'Craving relief, vacation mood, school holidays, energy only in mornings and evenings', ARRAY['Trips to Chorvoq reservoir and mountains', 'Children at summer camps and pools', 'Watermelon and melon after meals', 'Life moves to evenings']::text[], ARRAY['Melting ice', 'Condensation on a bottle', 'Heat haze on asphalt', 'Watermelon on ice', 'Pool splash']::text[], '{}'::jsonb, '{"featured_dish_keys": ["shashlik", "osh", "norin"], "sku_focus": ["0.5L PET", "1.5L PET"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('chilla_summer', 'Saratonda yoz chillasi', 'Летняя чилля (40 дней жары)', 'June 25 - August 5 (40 days)', 'GREGORIAN_RANGE', 6, 25, 8, 5, NULL, NULL, NULL, 60, 'Extreme thermal stress +40°C to +45°C (up to +47°C in Termez); rapid fluid and salt loss, headaches, heat exhaustion risk, loss of appetite in daytime', 'Physical exhaustion, irritability, desperate craving for cold, relief-seeking; nights become the social time', ARRAY['Staying indoors 12:00-17:00', 'Sleeping on tapchans in the courtyard at night', 'Watering courtyards to cool them', 'Late-night street food and family walks after 21:00', 'Cold dishes (okroshka, chalop) and watermelon']::text[], ARRAY['Thermometer at +43°C', 'Melting ice', 'Sun-bleached streets', 'Wet courtyard floor', 'Ice cracking in water']::text[], '{"note": "Encourage regular drinking; do not frame heat as fun for vulnerable groups (elders, babies)."}'::jsonb, '{"featured_dish_keys": ["shashlik", "somsa", "norin"], "sku_focus": ["0.5L PET", "1.5L PET"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('street_food_nights', 'Kechki ko''cha taomlari', 'Ночная уличная еда', 'Jun 1 - Sep 15', 'GREGORIAN_RANGE', 6, 1, 9, 15, NULL, NULL, NULL, 30, 'Evening still +30°C; heavy grilled food eaten late; accumulated dehydration from the day', 'Freedom, youth energy, friendship, fun', ARRAY['Shashlik stalls and tandir somsa at night', 'Friends meeting at Tashkent City park and Magic City', 'Late-night family walks', 'Watching football outdoors']::text[], ARRAY['Grill smoke under street lights', 'Neon city lights', 'Cold bottle passed between friends']::text[], '{}'::jsonb, '{"featured_dish_keys": ["shashlik", "somsa", "lagmon"], "sku_focus": ["0.5L PET", "0.33L Glass"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('independence_day', 'Mustaqillik kuni', 'День независимости', 'September 1 (campaign window Aug 25 - Sep 2)', 'FIXED_DATE', 8, 25, 9, 2, NULL, NULL, NULL, 85, 'Late summer heat +30-35°C; outdoor concerts and crowds; festive osh', 'National pride, unity, gratitude, hope for the future', ARRAY['Concerts and fireworks', 'Family osh', 'Flags on houses and cars', 'Children preparing for school start (Sept 2)']::text[], ARRAY['Uzbek flag (blue, white, green)', 'Fireworks', 'Stork (laylak) symbol', 'Crowds in city squares']::text[], '{"note": "Use state symbols respectfully; do not alter the flag or emblem."}'::jsonb, '{"featured_dish_keys": ["osh", "shashlik"], "sku_focus": ["0.5L PET", "1.5L PET"], "public_holiday_dates": ["09-01"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('harvest_period', 'Hosil mavsumi', 'Сезон урожая', 'Sep 1 - Oct 31', 'GREGORIAN_RANGE', 9, 1, 10, 31, NULL, NULL, NULL, 30, 'Warm days (+22-30°C), cool nights; outdoor physical work (cotton, grapes, fruit); abundant sweet fruit', 'Gratitude for abundance, satisfaction, generosity', ARRAY['Cotton and grape harvest', 'Melon and grape markets', 'Drying fruits on rooftops', 'Sharing harvest with neighbours']::text[], ARRAY['Grapes and pomegranates', 'Golden fields', 'Bazaar melon pyramids', 'Worker wiping sweat']::text[], '{}'::jsonb, '{"featured_dish_keys": ["osh", "kazan_kabob"], "sku_focus": ["5L/10L Family Pack", "1.5L PET"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('teachers_day', 'O''qituvchi va murabbiylar kuni', 'День учителей и наставников', 'October 1 (campaign window Sep 27 - Oct 1)', 'FIXED_DATE', 9, 27, 10, 1, NULL, NULL, NULL, 70, 'Mild autumn (+20-25°C); long working days in classrooms, dry throats from speaking', 'Gratitude, respect for mentors, nostalgia for school years', ARRAY['Flowers and gifts for teachers', 'Student performances', 'Visiting former teachers']::text[], ARRAY['Chalkboard', 'Bouquet of flowers', 'Teacher''s desk with a bottle of water', 'School bell']::text[], '{}'::jsonb, '{"featured_dish_keys": ["somsa"], "sku_focus": ["0.5L PET", "0.33L Glass"], "public_holiday_dates": ["10-01"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('autumn_weddings', 'To''y mavsumi', 'Свадебный сезон', 'Sep 1 - Nov 30', 'GREGORIAN_RANGE', 9, 1, 11, 30, NULL, NULL, NULL, 50, 'Multiple heavy feasts per week (nahor oshi at dawn, evening banquets for 300-1000 guests); little sleep, long hours of dancing, high salt and fat intake', 'Festive joy, family honour, generosity, pride; also fatigue for hosts', ARRAY['Nahor oshi (morning wedding osh for men)', 'Fotiha to''y (engagement)', 'Kelin salom (bride''s greeting)', 'Evening banquet with norin, salads and shashlik', 'Lazgi and andijan polka dances']::text[], ARRAY['Wedding kazan for 1000 guests', 'Karnay and surnay horns', 'Bride in white with atlas details', 'Laden dastarkhan', 'Glass bottles in rows on tables']::text[], '{"note": "Never show alcohol; position BioLife as the table water of choice for halal celebrations."}'::jsonb, '{"featured_dish_keys": ["osh", "norin", "shashlik"], "sku_focus": ["0.33L Glass", "1.5L PET"], "b2b_note": "Target wedding halls (to''yxona) and caterers with bulk offers"}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('ramadan', 'Ramazon oyi', 'Священный месяц Рамадан', 'Lunar Month 9 (Ramadan), ~29-30 days, shifts ~11 days earlier each year', 'HIJRI_LUNAR', NULL, NULL, NULL, NULL, 9, 1, 30, 100, 'Daytime fasting (no food or water from suhoor to iftar); dehydration builds through the day; low energy in the afternoon; at iftar the body needs gentle rehydration before heavy food', 'Spiritual clarity, patience, gratitude, generosity, family unity at iftar', ARRAY['Suhoor (saharlik) before dawn', 'Breaking the fast with dates and water at iftar (iftorlik)', 'Family and mahalla iftars', 'Taraweeh prayers at the mosque', 'Charity (sadaqa, fitr sadaqasi)']::text[], ARRAY['Crescent moon', 'Dates and a glass of water at sunset', 'Mosque silhouette at dusk', 'Lantern light', 'Family dastarkhan at iftar']::text[], '{"mode": "RELIGIOUS_SENSITIVE", "rules": ["Never depict eating or drinking during daylight fasting hours", "Show water only at suhoor or iftar", "Schedule posts after iftar and before suhoor where possible", "No music-heavy, party or dance content; calm, respectful tone", "No humour about fasting; no discounts framed as ''break the fast early''", "Do not quote Quran or hadith in ads without review by a qualified religious advisor"]}'::jsonb, '{"featured_dish_keys": ["shurva", "osh", "somsa"], "sku_focus": ["1.5L PET", "5L/10L Family Pack"]}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('ramazan_hayit', 'Ramazon hayiti', 'Ураза-байрам (Рамазан хайит)', 'Lunar Month 10, Day 1-3 (Eid al-Fitr)', 'HIJRI_LUNAR', NULL, NULL, NULL, NULL, 10, 1, 3, 110, 'Body re-adjusting to daytime eating after a month of fasting; many sweets and heavy meals in a short time', 'Joy, relief, forgiveness, family reunion, generosity to children and the needy', ARRAY['Eid prayer in the morning', 'Visiting elders and relatives, graves of ancestors', 'Children collecting treats', 'Open-house dastarkhans with sweets and osh']::text[], ARRAY['Crescent moon', 'New clothes', 'Children with gifts', 'Full dastarkhan', 'Morning mosque crowd']::text[], '{"mode": "RELIGIOUS_SENSITIVE", "rules": ["Greeting-led content (''Hayitingiz muborak bo''lsin''), soft product presence", "No party or alcohol context"]}'::jsonb, '{"featured_dish_keys": ["osh", "somsa", "manti"], "sku_focus": ["5L/10L Family Pack", "1.5L PET"], "public_holiday": true}'::jsonb);
INSERT INTO cultural_events_seasons (key, name_uz, name_ru, temporal_anchor, anchor_type, start_month, start_day, end_month, end_day, hijri_month, hijri_day_start, hijri_day_end, priority, physiological_state, emotional_state, cultural_rituals, semiotic_symbols, content_guardrails, metadata) VALUES ('kurban_hayit', 'Qurbon hayiti', 'Курбан-байрам (Курбан хайит)', 'Lunar Month 12, Day 10-12 (Eid al-Adha)', 'HIJRI_LUNAR', NULL, NULL, NULL, NULL, 12, 10, 12, 110, 'Very high meat intake (sacrificial lamb: shurva, osh, kabob) over several days; in recent years falls in late spring/summer heat', 'Devotion, generosity, sharing, family unity, gratitude', ARRAY['Eid prayer', 'Qurbonlik (sacrifice) and sharing meat with neighbours and the needy', 'Hosting guests for three days', 'Visiting elders']::text[], ARRAY['Crescent moon', 'Shared plates of meat', 'Open door of a home', 'Big family kazan']::text[], '{"mode": "RELIGIOUS_SENSITIVE", "rules": ["Do not show the sacrifice itself or blood", "Focus on sharing and hospitality", "Greeting-led content (''Qurbon hayitingiz muborak'')"]}'::jsonb, '{"featured_dish_keys": ["shurva", "osh", "kazan_kabob"], "sku_focus": ["5L/10L Family Pack", "1.5L PET"], "public_holiday": true}'::jsonb);
