INSERT INTO event_occurrences (event_id, year, start_date, end_date, is_confirmed, source) SELECT id, 2028, '2028-02-26', '2028-02-28', FALSE, 'Astronomical estimate (Eid al-Fitr 1449 AH); confirm with muslim.uz' FROM cultural_events_seasons WHERE key = 'ramazan_hayit';
INSERT INTO event_occurrences (event_id, year, start_date, end_date, is_confirmed, source) SELECT id, 2028, '2028-05-05', '2028-05-07', FALSE, 'Astronomical estimate (10 Dhu al-Hijjah 1449 AH); confirm with muslim.uz' FROM cultural_events_seasons WHERE key = 'kurban_hayit';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'New Year is the most nostalgic family moment of the year; memory-driven warmth (''the table where everyone is together'') drives sharing and saves more than a thirst trigger, which is weak in cold weather.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'new_year' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Secondary: midnight countdown and fireworks allow short high-energy ''first sip of the year'' clips for youth audiences.', 0.4 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'new_year' AND f.framework_name = 'PEPSI_BEHAVIORAL_DOPAMINE';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Thirst is low in cold weather, so contrast/refreshment messages under-perform; habit and home-comfort storytelling (water on the family table next to hot shurva) builds consumption of family packs.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'winter_cold_season' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Pride and respect are emotional-memory drivers; father-son and family stories fit better than sensory hooks.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'homeland_defenders_day' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'The audience wants to shake off winter heaviness; ''fresh start'' combines novelty (dopamine) with seasonal tradition, a natural bridge to Navruz.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'spring_preparation' AND f.framework_name = 'HYBRID_SPRING_RENEWAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Gratitude to mothers and wives is deeply emotional; care-giving narratives (pouring water for her) create positive brand memory and gifting of glass SKUs.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'womens_day' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Navruz is literally ''new day'': renewal plus ancient tradition. Hybrid framing connects purity of water with purity of a new beginning and communal sumalak ritual.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'navruz' AND f.framework_name = 'HYBRID_SPRING_RENEWAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Secondary for long-form family/mahalla stories around the sumalak kazan.', 0.6 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'navruz' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Visual freshness of blossoms mirrors product purity; first outdoor thirst creates light refreshment moments without aggressive heat framing.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'spring_blossoms' AND f.framework_name = 'HYBRID_SPRING_RENEWAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Choyxona is about friendship and ritual; social belonging drives repeat group purchases (1.5L on the tapchan).', 0.7 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'choyxona_opening' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Primary: afternoons already reach +28-30°C and the kazan/grill fire vs ice-bucket contrast gives a strong sensory hook for short Reels.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'choyxona_opening' AND f.framework_name = 'PEPSI_BEHAVIORAL_DOPAMINE';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Only respectful, memory-based storytelling is appropriate; sensory or sales hooks would damage the brand.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'memorial_day' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Heat creates real physiological thirst; instant-relief contrast (heat vs ice) matches the moment of need and converts to immediate purchase.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'summer_season' AND f.framework_name = 'PEPSI_BEHAVIORAL_DOPAMINE';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'At +40-45°C the thirst drive dominates attention; ultra-short sensory Reels (ice, condensation, first sip sound) trigger the strongest reward anticipation and impulse buys of chilled 0.5L.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'chilla_summer' AND f.framework_name = 'PEPSI_BEHAVIORAL_DOPAMINE';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Young audience, fire and smoke vs cold bottle, fast social energy - ideal for dopamine-driven short content.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'street_food_nights' AND f.framework_name = 'PEPSI_BEHAVIORAL_DOPAMINE';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'National pride and unity are collective-memory emotions; ''water of our land for our people'' storytelling fits a local brand.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'independence_day' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Secondary: concerts and fireworks in late-summer heat allow energetic refreshment clips.', 0.5 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'independence_day' AND f.framework_name = 'PEPSI_BEHAVIORAL_DOPAMINE';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Gratitude and abundance are tradition-based emotions; honest-work and family-harvest stories build trust in a natural product.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'harvest_period' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Nostalgia for school and respect for mentors are memory-driven; gratitude stories are highly shareable.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'teachers_day' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Weddings are about family honour and tradition; being ''the water on every wedding table'' anchors the brand in the most important life events.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'autumn_weddings' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Secondary: after heavy norin and osh, a sensory ''reset'' clip (cold sip after fat) works for guests and dance-floor moments.', 0.5 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'autumn_weddings' AND f.framework_name = 'PEPSI_BEHAVIORAL_DOPAMINE';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Ramadan is spiritual and family-centred; iftar togetherness and gratitude for the first sip of water after fasting are powerful emotional memories. Dopamine/craving framing during fasting hours would be disrespectful.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'ramadan' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Eid is family reunion, forgiveness and generosity; greeting-led emotional content earns shares and goodwill.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'ramazan_hayit' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO event_framework_mappings (event_id, framework_id, selection_rationale, weight) SELECT e.id, f.id, 'Hospitality and sharing are the core of the holiday; storytelling about guests and family tables fits, with the product as the host''s water.', 1.0 FROM cultural_events_seasons e, psychological_frameworks f WHERE e.key = 'kurban_hayit' AND f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO annual_calendar_grid (month_number, season_name, average_temperature_range, avg_temp_min_c, avg_temp_max_c, primary_cultural_context, default_dish_pairings, active_framework_id) SELECT 1, 'Winter', '-3°C … +6°C', -3, 6, 'New Year holidays, Homeland Defenders'' Day, deep winter, indoor family meals', ARRAY(SELECT n.id FROM unnest(ARRAY['shurva', 'manti', 'osh']::text[]) WITH ORDINALITY k(key, ord) JOIN national_dishes_pairing n ON n.key = k.key ORDER BY k.ord), f.id FROM psychological_frameworks f WHERE f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO annual_calendar_grid (month_number, season_name, average_temperature_range, avg_temp_min_c, avg_temp_max_c, primary_cultural_context, default_dish_pairings, active_framework_id) SELECT 2, 'Winter', '-1°C … +9°C', -1, 9, 'Late winter, preparation for spring, end-of-winter fatigue', ARRAY(SELECT n.id FROM unnest(ARRAY['lagmon', 'shurva', 'somsa']::text[]) WITH ORDINALITY k(key, ord) JOIN national_dishes_pairing n ON n.key = k.key ORDER BY k.ord), f.id FROM psychological_frameworks f WHERE f.framework_name = 'COCA_COLA_EMOTIONAL';
INSERT INTO annual_calendar_grid (month_number, season_name, average_temperature_range, avg_temp_min_c, avg_temp_max_c, primary_cultural_context, default_dish_pairings, active_framework_id) SELECT 3, 'Spring', '+4°C … +16°C', 4, 16, 'Women''s Day (Mar 8), Navruz (Mar 21), sumalak, first blossoms', ARRAY(SELECT n.id FROM unnest(ARRAY['sumalak', 'somsa', 'osh']::text[]) WITH ORDINALITY k(key, ord) JOIN national_dishes_pairing n ON n.key = k.key ORDER BY k.ord), f.id FROM psychological_frameworks f WHERE f.framework_name = 'HYBRID_SPRING_RENEWAL';
INSERT INTO annual_calendar_grid (month_number, season_name, average_temperature_range, avg_temp_min_c, avg_temp_max_c, primary_cultural_context, default_dish_pairings, active_framework_id) SELECT 4, 'Spring', '+10°C … +23°C', 10, 23, 'Blossoms and tulips, picnics, opening of outdoor choyxonas', ARRAY(SELECT n.id FROM unnest(ARRAY['shashlik', 'somsa', 'osh']::text[]) WITH ORDINALITY k(key, ord) JOIN national_dishes_pairing n ON n.key = k.key ORDER BY k.ord), f.id FROM psychological_frameworks f WHERE f.framework_name = 'HYBRID_SPRING_RENEWAL';
