INSERT INTO inference_rules (rule_key, description, priority, condition, action) VALUES ('heat_extreme', 'Live temperature ≥ 35°C overrides to the refreshment framework (unless a religious guardrail rule fires later).', 20, '{"temp_gte": 35}'::jsonb, '{"framework": "PEPSI_BEHAVIORAL_DOPAMINE", "sku": "0.5L PET", "tone_modifier": "Mention the live temperature on screen", "visual_modifier": "Heat haze + macro condensation in first 1.5s", "note": "Live temperature ≥35°C: thirst drive dominates, refreshment contrast converts best."}'::jsonb);
INSERT INTO inference_rules (rule_key, description, priority, condition, action) VALUES ('heat_warm', '28-34°C: keep the base framework but add refreshment cues.', 15, '{"temp_gte": 28, "temp_lte": 34.9}'::jsonb, '{"tone_modifier": "Add one cold-sip sensory beat", "visual_modifier": "Show visible condensation on the bottle"}'::jsonb);
INSERT INTO inference_rules (rule_key, description, priority, condition, action) VALUES ('cold_weather', '≤ 5°C: avoid ice imagery; emphasise daily hydration and warm homes.', 15, '{"temp_lte": 5}'::jsonb, '{"tone_modifier": "Hydration habit, not ice-cold relief", "visual_modifier": "No ice cubes; room-temperature pour, warm interiors"}'::jsonb);
INSERT INTO inference_rules (rule_key, description, priority, condition, action) VALUES ('trend_hook', 'If a trending topic is supplied, use it only as the opening hook; framework stays the same.', 10, '{"trend_present": true}'::jsonb, '{"tone_modifier": "Open with the trend in the first 2 seconds, then return to the framework story; skip trends that conflict with guardrails"}'::jsonb);
INSERT INTO inference_rules (rule_key, description, priority, condition, action) VALUES ('religious_guardrail', 'During Ramadan and both Hayits, always use the emotional framework, even in heat.', 100, '{"event_key_in": ["ramadan", "ramazan_hayit", "kurban_hayit"]}'::jsonb, '{"framework": "COCA_COLA_EMOTIONAL", "tone_modifier": "Calm, respectful, family and gratitude; water only at iftar/suhoor", "visual_modifier": "Dusk/pre-dawn light, no daytime drinking", "note": "Religious period: emotional, respectful framing overrides temperature rules."}'::jsonb);
INSERT INTO inference_rules (rule_key, description, priority, condition, action) VALUES ('memorial_low_key', 'May 9: remembrance only.', 90, '{"event_key_in": ["memorial_day"]}'::jsonb, '{"framework": "COCA_COLA_EMOTIONAL", "tone_modifier": "No sales, no humour", "note": "Memorial Day: respectful, low-key content only."}'::jsonb);
